// Generated by scripts/gen-map-bundle.mjs from src/maps/kit/random.ts. Do not edit.
// Random maps, from a seed: a house split into furnished rooms, a crypt of chambers and passages, a
// village on a river. The public map maker's "Carte au hasard", a starting point to edit, and test
// fixtures (every generated map must be free of mapProblems).
import { emptyMap, footprint, mapProblems, type MapDoc, type MapItem, type MapKind } from './model.ts'
import { STAMPS } from './stamps.ts'

type Lang = 'fr' | 'en'

/** mulberry32. */
function rng(seed: number) {
  let a = seed | 0
  const next = () => {
    a = (a + 0x6d2b79f5) | 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
  return {
    next,
    int: (lo: number, hi: number) => lo + Math.floor(next() * (hi - lo + 1)),
    pick: <T>(xs: readonly T[]): T => xs[Math.floor(next() * xs.length)],
    chance: (p: number) => next() < p,
  }
}
type Rng = ReturnType<typeof rng>

/** A grid of characters being drawn. */
class Canvas {
  cols: number
  rows: number
  cells: string[][]
  taken: boolean[][]
  constructor(cols: number, rows: number, fill = ' ') {
    this.cols = cols
    this.rows = rows
    this.cells = Array.from({ length: rows }, () => Array.from({ length: cols }, () => fill))
    this.taken = Array.from({ length: rows }, () => Array.from({ length: cols }, () => false))
  }
  in(x: number, y: number) {
    return x >= 0 && y >= 0 && x < this.cols && y < this.rows
  }
  get(x: number, y: number) {
    return this.in(x, y) ? this.cells[y][x] : ' '
  }
  set(x: number, y: number, c: string) {
    if (this.in(x, y)) this.cells[y][x] = c
  }
  rect(x: number, y: number, w: number, h: number, c: string) {
    for (let j = y; j < y + h; j++) for (let i = x; i < x + w; i++) this.set(i, j, c)
  }
  /** Marks cells nothing may be put on (in front of a door). */
  reserve(x: number, y: number) {
    if (this.in(x, y)) this.taken[y][x] = true
  }
  rows_(): string[] {
    return this.cells.map((r) => r.join(''))
  }
}

/** Puts a stamp if its footprint is free and on allowed ground; returns whether it fitted. */
function place(cv: Canvas, items: MapItem[], item: MapItem, ground: (c: string) => boolean): boolean {
  if (!STAMPS[item.t]) return false
  const [w, h] = footprint(item)
  const x0 = Math.floor(item.x)
  const y0 = Math.floor(item.y)
  const x1 = Math.ceil(item.x + w)
  const y1 = Math.ceil(item.y + h)
  for (let y = y0; y < y1; y++) for (let x = x0; x < x1; x++) if (!cv.in(x, y) || cv.taken[y][x] || !ground(cv.get(x, y))) return false
  for (let y = y0; y < y1; y++) for (let x = x0; x < x1; x++) cv.taken[y][x] = true
  items.push(item)
  return true
}

/** Where a room's name fits: the lowest row of the room whose middle cells are free. */
function labelSpot(cv: Canvas, r: Room): [number, number] {
  const mid = r.x + r.w / 2
  const cells = [Math.floor(mid - 1), Math.floor(mid), Math.ceil(mid)].filter((x) => x >= r.x && x < r.x + r.w)
  for (let y = r.y + r.h - 1; y >= r.y; y--) if (cells.every((x) => !cv.taken[y]?.[x])) return [mid, y + 0.5]
  return [mid, r.y + r.h - 0.5]
}

// ------------------------------------------------------------------ building

interface Room {
  x: number
  y: number
  w: number
  h: number
}

const ROOMS = {
  fr: { salon: 'Salon', bureau: 'Bureau', biblio: 'Bibliothèque', cuisine: 'Cuisine', manger: 'Salle à manger', chambre: 'Chambre', bains: 'Salle de bains', reserve: 'Débarras', hall: 'Vestibule' },
  en: { salon: 'Drawing room', bureau: 'Study', biblio: 'Library', cuisine: 'Kitchen', manger: 'Dining room', chambre: 'Bedroom', bains: 'Bathroom', reserve: 'Storeroom', hall: 'Hall' },
}
type RoomType = keyof (typeof ROOMS)['fr']

const HOUSES = {
  fr: ['Villa des Tilleuls', 'Maison Valadier', 'Le Logis du Notaire', 'Pavillon Berthelot', 'La Maison aux Volets Clos'],
  en: ['Linden House', 'The Ashcombe Residence', 'The Notary’s House', 'Wexley Lodge', 'The House of Shuttered Windows'],
}

function furnish(cv: Canvas, items: MapItem[], r: Room, type: RoomType, rand: Rng) {
  const floor = (c: string) => c === '.'
  const put = (t: string, x: number, y: number, rot: 0 | 1 | 2 | 3 = 0) => place(cv, items, { t, x, y, ...(rot ? { r: rot } : {}) }, floor)
  const { x, y, w, h } = r
  const right = x + w
  const bottom = y + h
  switch (type) {
    case 'salon':
      put('fireplace', x + Math.floor(w / 2) - 1, y)
      put('rug', x + Math.floor(w / 2) - 1, y + 2)
      put('sofa', x + Math.floor(w / 2) - 1, bottom - 1, 2)
      put('armchair', x, y + 1, 1)
      if (w >= 8) put('piano', right - 2, bottom - 2)
      put('plant', right - 1, y)
      break
    case 'bureau':
      put('bookshelf', x, y)
      put('bookshelf', x + 2, y)
      put('desk', x + Math.floor(w / 2) - 1, y + 2)
      put('armchair', right - 1, bottom - 1)
      break
    case 'biblio':
      for (let i = x; i + 2 <= right; i += 2) put('bookshelf', i, y)
      for (let i = x; i + 2 <= right; i += 2) put('bookshelf', i, bottom - 1, 2)
      put('table', x + Math.floor(w / 2) - 1, y + Math.floor(h / 2))
      put('chair', x + Math.floor(w / 2) - 1, y + Math.floor(h / 2) - 1)
      break
    case 'cuisine':
      put('counter', x, y)
      put('stove', x + 2, y)
      put('table', x + Math.floor(w / 2) - 1, y + Math.floor(h / 2))
      put('barrels', right - 1, bottom - 1)
      put('crates', right - 1, y)
      break
    case 'manger':
      put('table', x + Math.floor(w / 2) - 1, y + Math.floor(h / 2))
      put('chair', x + Math.floor(w / 2) - 1, y + Math.floor(h / 2) - 1)
      put('chair', x + Math.floor(w / 2), y + Math.floor(h / 2) - 1)
      put('chair', x + Math.floor(w / 2) - 1, y + Math.floor(h / 2) + 1, 2)
      put('chair', x + Math.floor(w / 2), y + Math.floor(h / 2) + 1, 2)
      put('wardrobe', x, y)
      break
    case 'chambre':
      if (!put('double-bed', x + 1, y)) put('bed', x + 1, y)
      put('wardrobe', right - 1, y)
      put('chest', x + 1, bottom - 1)
      if (!put('rug', x, y + 2)) put('chair', right - 1, bottom - 1)
      break
    case 'bains':
      put('bathtub', x, y)
      put('plant', right - 1, bottom - 1)
      break
    case 'reserve':
      put('crates', x, y)
      put('barrels', x + 1, y)
      put('crates', right - 1, bottom - 1)
      put('chest', right - 1, y)
      break
    case 'hall':
      put('stairs-up', x + (rand.chance(0.5) ? 0 : w - 1), y)
      put('plant', right - 1, bottom - 1)
      break
  }
}

function building(seed: number, lang: Lang): MapDoc {
  const rand = rng(seed)
  const W = rand.int(20, 28)
  const H = rand.int(13, 17)
  const cols = W + 2
  const rows = H + 4
  const cv = new Canvas(cols, rows)
  const bx = 1
  const by = 1
  // Outer walls, then split the inside into rooms.
  cv.rect(bx, by, W, H, '#')
  cv.rect(bx + 1, by + 1, W - 2, H - 2, '.')
  const rooms: Room[] = []
  const split = (r: Room, depth: number) => {
    const canV = r.w >= 9
    const canH = r.h >= 9
    if ((!canV && !canH) || (depth > 2 && rand.chance(0.35)) || r.w * r.h < 30) {
      rooms.push(r)
      return
    }
    const vertical = canV && (!canH || r.w > r.h || (r.w === r.h && rand.chance(0.5)))
    if (vertical) {
      const at = r.x + rand.int(4, r.w - 5)
      for (let y = r.y - 1; y <= r.y + r.h; y++) cv.set(at, y, '#')
      const door = rand.int(r.y + 1, r.y + r.h - 2)
      cv.set(at, door, 'd')
      split({ x: r.x, y: r.y, w: at - r.x, h: r.h }, depth + 1)
      split({ x: at + 1, y: r.y, w: r.x + r.w - at - 1, h: r.h }, depth + 1)
    } else {
      const at = r.y + rand.int(4, r.h - 5)
      for (let x = r.x - 1; x <= r.x + r.w; x++) cv.set(x, at, '#')
      const door = rand.int(r.x + 1, r.x + r.w - 2)
      cv.set(door, at, 'd')
      split({ x: r.x, y: r.y, w: r.w, h: at - r.y }, depth + 1)
      split({ x: r.x, y: at + 1, w: r.w, h: r.y + r.h - at - 1 }, depth + 1)
    }
  }
  split({ x: bx + 1, y: by + 1, w: W - 2, h: H - 2 }, 0)
  // A split wall may have been crossed by a later one exactly where an earlier door was: put doors
  // back where both sides are floor.
  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      if (cv.get(x, y) !== 'd') continue
      const across = cv.get(x - 1, y) === '.' && cv.get(x + 1, y) === '.'
      const down = cv.get(x, y - 1) === '.' && cv.get(x, y + 1) === '.'
      if (!across && !down) cv.set(x, y, '#')
    }
  }
  // Rooms whose door was lost: open a door in a wall shared with a neighbour.
  const reachable = () => {
    const seen = new Set<string>()
    const start = rooms[0]
    const stack = [[start.x, start.y]]
    seen.add(`${start.x},${start.y}`)
    while (stack.length) {
      const [x, y] = stack.pop()!
      for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const nx = x + dx
        const ny = y + dy
        const c = cv.get(nx, ny)
        if ((c === '.' || c === 'd') && !seen.has(`${nx},${ny}`)) {
          seen.add(`${nx},${ny}`)
          stack.push([nx, ny])
        }
      }
    }
    return seen
  }
  for (let guard = 0; guard < 20; guard++) {
    const seen = reachable()
    const lost = rooms.find((r) => !seen.has(`${r.x},${r.y}`))
    if (!lost) break
    let opened = false
    for (let y = lost.y - 1; y <= lost.y + lost.h && !opened; y++) {
      for (let x = lost.x - 1; x <= lost.x + lost.w && !opened; x++) {
        if (cv.get(x, y) !== '#') continue
        const pairs: [number, number, number, number][] = [[x - 1, y, x + 1, y], [x, y - 1, x, y + 1]]
        for (const [ax, ay, cx, cy] of pairs) {
          if (cv.get(ax, ay) === '.' && cv.get(cx, cy) === '.' && seen.has(`${ax},${ay}`) !== seen.has(`${cx},${cy}`)) {
            cv.set(x, y, 'd')
            opened = true
            break
          }
        }
      }
    }
    if (!opened) break
  }
  // The front door, windows on the outside walls.
  // The front door: on the bottom wall, under a room (not where an inside wall meets it).
  const fronts: number[] = []
  for (let x = bx + 2; x <= bx + W - 3; x++) if (cv.get(x, by + H - 2) === '.' && cv.get(x - 1, by + H - 2) === '.' && cv.get(x + 1, by + H - 2) === '.') fronts.push(x)
  const front = fronts.length ? rand.pick(fronts) : bx + 2
  cv.set(front, by + H - 1, 'd')
  for (let x = bx + 2; x < bx + W - 2; x++) {
    for (const y of [by, by + H - 1]) if (cv.get(x, y) === '#' && cv.get(x, y === by ? y + 1 : y - 1) === '.' && cv.get(x - 1, y) === '#' && cv.get(x + 1, y) === '#' && x % 4 === 2) cv.set(x, y, 'w')
  }
  for (let y = by + 2; y < by + H - 2; y++) {
    for (const x of [bx, bx + W - 1]) if (cv.get(x, y) === '#' && cv.get(x === bx ? x + 1 : x - 1, y) === '.' && cv.get(x, y - 1) === '#' && cv.get(x, y + 1) === '#' && y % 4 === 1) cv.set(x, y, 'w')
  }
  // Garden in front, a path to the door.
  for (let y = by + H; y < rows; y++) for (let x = 0; x < cols; x++) cv.set(x, y, '"')
  for (let y = by + H; y < rows; y++) cv.set(front, y, ':')
  // Keep the cells in front of doors free.
  for (let y = 0; y < rows; y++) for (let x = 0; x < cols; x++) if (cv.get(x, y) === 'd') for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) cv.reserve(x + dx, y + dy)

  // Name and furnish the rooms, largest first.
  const items: MapItem[] = []
  const labels: MapDoc['labels'] = []
  const byArea = [...rooms].sort((a, b) => b.w * b.h - a.w * a.h)
  const kinds: RoomType[] = ['salon', 'manger', 'cuisine', 'bureau', 'biblio', 'chambre', 'chambre', 'bains', 'reserve']
  const entrance = rooms.find((r) => front >= r.x && front < r.x + r.w && r.y + r.h === by + H - 1)
  byArea.forEach((r, i) => {
    let type: RoomType = r === entrance && r.w * r.h < 40 ? 'hall' : (kinds[i] ?? 'reserve')
    if (r.w * r.h < 14) type = 'reserve'
    furnish(cv, items, r, type, rand)
    const [lx, ly] = labelSpot(cv, r)
    labels.push({ text: ROOMS[lang][type], x: lx, y: ly })
  })
  for (let n = 0; n < 6; n++) place(cv, items, { t: rand.pick(['tree', 'bush', 'tree']), x: rand.int(0, cols - 1), y: rand.int(by + H, rows - 1) }, (c) => c === '"')

  return { ...emptyMap('building', cols, rows, rand.pick(HOUSES[lang])), ground: cv.rows_(), items, labels }
}

// ------------------------------------------------------------------ underground

const CHAMBERS = {
  fr: { first: 'Entrée', ossuary: 'Ossuaire', chapel: 'Chapelle', well: 'Puits', tombs: 'Tombeaux', secret: 'Sanctuaire caché', hall: 'Salle des piliers' },
  en: { first: 'Entrance', ossuary: 'Ossuary', chapel: 'Chapel', well: 'Well', tombs: 'Tombs', secret: 'Hidden shrine', hall: 'Pillared hall' },
}
const CRYPTS = { fr: ['La crypte de Saint-Aubin', 'Les caves de l’abbaye', 'Le souterrain des Pénitents', 'Les carrières oubliées'], en: ['The Crypt of St Aubin', 'The Abbey Cellars', 'The Penitents’ Tunnel', 'The Forgotten Quarries'] }

function underground(seed: number, lang: Lang): MapDoc {
  const rand = rng(seed)
  const cols = rand.int(28, 36)
  const rows = rand.int(18, 24)
  const cv = new Canvas(cols, rows)
  const rooms: Room[] = []
  for (let tries = 0; tries < 200 && rooms.length < 7; tries++) {
    const w = rand.int(4, 8)
    const h = rand.int(3, 6)
    const x = rand.int(1, cols - w - 1)
    const y = rand.int(1, rows - h - 1)
    if (rooms.some((r) => x < r.x + r.w + 2 && x + w + 2 > r.x && y < r.y + r.h + 2 && y + h + 2 > r.y)) continue
    rooms.push({ x, y, w, h })
  }
  rooms.sort((a, b) => a.x - b.x)
  for (const r of rooms) {
    cv.rect(r.x, r.y, r.w, r.h, '.')
    // Knock a corner or two off, so chambers aren't all boxes.
    if (rand.chance(0.6)) cv.set(r.x, r.y, ' ')
    if (rand.chance(0.6)) cv.set(r.x + r.w - 1, r.y + r.h - 1, ' ')
  }
  const centre = (r: Room) => [r.x + Math.floor(r.w / 2), r.y + Math.floor(r.h / 2)]
  const hidden = new Set<string>()
  // A passage from room to room; `door` goes on its first cell out of `a` (a secret door hides the
  // rest of the passage too).
  const dig = (a: Room, b: Room, door: string) => {
    const [bx, by] = centre(b)
    let [x, y] = centre(a)
    const path: [number, number][] = []
    const stepX = () => {
      while (x !== bx) {
        x += Math.sign(bx - x)
        path.push([x, y])
      }
    }
    const stepY = () => {
      while (y !== by) {
        y += Math.sign(by - y)
        path.push([x, y])
      }
    }
    if (rand.chance(0.5)) {
      stepX()
      stepY()
    } else {
      stepY()
      stepX()
    }
    let doorSet = !door
    for (const [px, py] of path) {
      const inRoom = rooms.some((r) => px >= r.x && px < r.x + r.w && py >= r.y && py < r.y + r.h)
      if (inRoom) {
        // A knocked-off corner in the way: the passage goes through it.
        if (cv.get(px, py) === ' ') cv.set(px, py, '.')
        continue
      }
      if (cv.get(px, py) !== ' ') continue
      if (door === 's' && doorSet) hidden.add(`${px},${py}`)
      cv.set(px, py, doorSet ? '.' : door)
      doorSet = true
    }
  }
  const secret = rooms.length >= 5 ? rooms[rooms.length - 1] : null
  for (let i = 1; i < rooms.length; i++) dig(rooms[i - 1], rooms[i], rooms[i] === secret ? 's' : rand.chance(0.25) ? 'd' : '')
  // A pool.
  if (rand.chance(0.6)) {
    const r = rand.pick(rooms.filter((r) => r !== secret && r !== rooms[0]))
    if (r && r.w >= 5) cv.rect(r.x + r.w - 2, r.y + 1, 2, Math.min(2, r.h - 2), '~')
  }
  for (let y = 0; y < rows; y++) for (let x = 0; x < cols; x++) if (cv.get(x, y) === 'd' || cv.get(x, y) === 's') for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) cv.reserve(x + dx, y + dy)

  const items: MapItem[] = []
  const labels: MapDoc['labels'] = []
  const words = CHAMBERS[lang]
  const floor = (c: string) => c === '.'
  const put = (t: string, x: number, y: number, extra: Partial<MapItem> = {}) => place(cv, items, { t, x, y, ...extra }, floor)
  const themes = (['ossuary', 'chapel', 'tombs', 'hall', 'well'] as const).slice().sort(() => rand.next() - 0.5)
  rooms.forEach((r, i) => {
    const [cx, cy] = centre(r)
    let name = ''
    if (i === 0) {
      if (!put('stairs-up', r.x + 1, r.y + Math.max(0, r.h - 3))) put('ladder', r.x + 1, r.y + 1)
      name = words.first
    } else if (r === secret) {
      if (!put('ritual-circle', cx - 1, cy - 1) && !put('altar', cx - 1, cy)) put('idol', cx, cy)
      name = words.secret
    } else {
      const theme = themes[(i - 1) % themes.length]
      name = words[theme]
      if (theme === 'ossuary') for (let n = 0; n < 4; n++) put('bones', rand.int(r.x, r.x + r.w - 1), rand.int(r.y, r.y + r.h - 1))
      if (theme === 'chapel') {
        put('altar', cx - 1, r.y)
        put('sconce', r.x, r.y)
      }
      if (theme === 'tombs') for (let x = r.x + 1; x + 1 <= r.x + r.w; x += 2) put(rand.chance(0.6) ? 'sarcophagus' : 'coffin', x, r.y)
      if (theme === 'hall') for (const [x, y] of [[r.x + 1, r.y + 1], [r.x + r.w - 2, r.y + 1], [r.x + 1, r.y + r.h - 2], [r.x + r.w - 2, r.y + r.h - 2]]) put('pillar', x, y)
      if (theme === 'well') put('well', cx, cy)
      if (rand.chance(0.4)) put('rubble', rand.int(r.x, r.x + r.w - 1), rand.int(r.y, r.y + r.h - 1))
    }
    const [nx, ny] = labelSpot(cv, r)
    labels.push({ text: name, x: nx, y: ny, ...(r === secret ? { secret: true } : {}) })
  })
  const doc: MapDoc = { ...emptyMap('underground', cols, rows, rand.pick(CRYPTS[lang])), ground: cv.rows_(), items, labels }
  // A pool across the only way through: drain it.
  if (mapProblems(doc).length) doc.ground = doc.ground.map((r) => r.replaceAll('~', '.'))
  if (secret) {
    const inSecret = (x: number, y: number) => hidden.has(`${x},${y}`) || (x >= secret.x && x < secret.x + secret.w && y >= secret.y && y < secret.y + secret.h)
    doc.secret = Array.from({ length: rows }, (_, y) => Array.from({ length: cols }, (_, x) => (inSecret(x, y) ? 'x' : '.')).join(''))
  }
  return doc
}

// ------------------------------------------------------------------ outdoor

const VILLAGES = { fr: ['Saint-Firmin-des-Bois', 'Vauclère', 'Les Hauts-Prés', 'Morsange', 'Sainte-Ombre'], en: ['Ashby Fen', 'Holloway Cross', 'Little Wendham', 'Marlow Ford', 'Saint Brannoc'] }
const PLACES = {
  fr: { church: 'Église', square: 'Place', river: 'La rivière', inn: 'Auberge', mill: 'Moulin', farm: 'Ferme', cemetery: 'Cimetière', woods: 'Les bois' },
  en: { church: 'Church', square: 'Square', river: 'The river', inn: 'Inn', mill: 'Mill', farm: 'Farm', cemetery: 'Churchyard', woods: 'The woods' },
}

function outdoor(seed: number, lang: Lang): MapDoc {
  const rand = rng(seed)
  const cols = rand.int(34, 42)
  const rows = rand.int(24, 28)
  const cv = new Canvas(cols, rows, '"')
  const words = PLACES[lang]
  // A river down one side, winding.
  const riverLeft = rand.chance(0.5)
  let rx = riverLeft ? rand.int(3, 6) : cols - rand.int(6, 9)
  const riverAt: number[] = []
  for (let y = 0; y < rows; y++) {
    riverAt.push(rx)
    cv.rect(rx, y, 3, 1, '~')
    if (y % 3 === 2) rx = Math.max(1, Math.min(cols - 4, rx + rand.int(-1, 1)))
  }
  // The main road across, a lane down; the square where they meet.
  const ry = rand.int(10, rows - 11)
  const lx = riverLeft ? rand.int(Math.floor(cols / 2), cols - 10) : rand.int(9, Math.floor(cols / 2))
  for (let x = 0; x < cols; x++) if (cv.get(x, ry) !== '~') cv.rect(x, ry, 1, 2, '=')
  for (let y = 0; y < rows; y++) if (cv.get(lx, y) === '"') cv.set(lx, y, ':')
  cv.rect(lx - 2, ry - 2, 6, 6, '+')
  const items: MapItem[] = []
  const labels: MapDoc['labels'] = []
  // The bridge over the river where the road crosses it.
  const bx = riverAt[ry]
  items.push({ t: 'bridge', x: bx, y: ry, r: 1 })
  for (let x = bx; x < bx + 3; x++) for (let y = ry; y < ry + 1; y++) cv.reserve(x, y)
  const grass = (c: string) => c === '"'
  const put = (t: string, x: number, y: number, extra: Partial<MapItem> = {}) => place(cv, items, { t, x, y, ...extra }, grass)
  place(cv, items, { t: 'well', x: lx + 2, y: ry - 2 }, (c) => c === '+')
  // The church beside the square, its churchyard.
  const churchX = lx + 5
  if (put('church', churchX, ry - 6)) {
    labels.push({ text: words.church, x: churchX + 1.5, y: ry - 6.5 })
    for (let n = 0; n < 8; n++) put('gravestone', churchX + 3 + (n % 4), ry - 6 + Math.floor(n / 4) * 2)
  }
  labels.push({ text: words.square, x: lx + 1, y: ry + 4.5 })
  // Houses along the road and the lane.
  for (let n = 0; n < 40 && items.filter((i) => i.t.includes('house')).length < 9; n++) {
    const t = rand.chance(0.7) ? 'house' : 'long-house'
    const side = rand.chance(0.5)
    const along = rand.chance(0.6)
    const x = along ? rand.int(0, cols - 3) : lx + (side ? 2 : -3)
    const y = along ? (side ? ry - 3 : ry + 3) : rand.int(0, rows - 3)
    put(t, x, y)
  }
  if (put('barn', riverLeft ? cols - 5 : 1, rows - 4)) labels.push({ text: words.farm, x: riverLeft ? cols - 3.5 : 2.5, y: rows - 4.5 })
  put('haystack', riverLeft ? cols - 6 : 5, rows - 3)
  // Woods in the far corner.
  const wx = riverLeft ? cols - 10 : 1
  for (let n = 0; n < 26; n++) put(rand.chance(0.6) ? 'conifer' : 'tree', wx + rand.int(0, 8), rand.int(0, 6), rand.chance(0.3) ? { s: 1.5 } : {})
  labels.push({ text: words.woods, x: wx + 4.5, y: 3 })
  for (let n = 0; n < 14; n++) put(rand.pick(['tree', 'bush', 'bush', 'rocks']), rand.int(0, cols - 1), rand.int(0, rows - 1))
  labels.push({ text: words.river, x: riverAt[Math.floor(rows / 4)] + 1.5, y: Math.floor(rows / 4) })
  for (let n = 0; n < 3; n++) put('boat', riverAt[rows - 5] + 1, rows - 5)

  // Lamps on the square.
  place(cv, items, { t: 'lamppost', x: lx - 2, y: ry - 2 }, (c) => c === '+')
  place(cv, items, { t: 'lamppost', x: lx + 3, y: ry + 3 }, (c) => c === '+')
  return { ...emptyMap('outdoor', cols, rows, rand.pick(VILLAGES[lang])), ground: cv.rows_(), items, labels }
}

/** A random map of this kind. Same seed and language, same map. */
export function randomMap(kind: MapKind, seed: number, lang: Lang = 'fr'): MapDoc {
  if (kind === 'underground') return underground(seed, lang)
  if (kind === 'outdoor') return outdoor(seed, lang)
  return building(seed, lang)
}
